initShipUpgrade:
query initShipUpgrade {
  ships { id name manufacturer { id name } focus type flyableStatus owned msrp link
    skus { id title available price body unlimitedStock availableStock } }
  manufacturers { id name }
  app { version env pricing { currencyCode currencySymbol exchangeRate exponent taxRate isTaxInclusive } mode isAnonymous buyback { credit } }
}

filterShips:
query filterShips($fromId: Int, $toId: Int, $fromFilters: [FilterConstraintValues], $toFilters: [FilterConstraintValues]) {
  from(to: $toId, filters: $fromFilters) { ships { id } }
  to(from: $fromId, filters: $toFilters) {
    ships { id skus { id price upgradePrice unlimitedStock showStock available availableStock } }
  }
}

getShipDetails:
query getShipDetails($id: Int!, $fromShipId: Int) {
  ship(id: $id, from: $fromShipId) {
    id skus { id title price upgradePrice unlimitedStock showStock available availableStock limitedTimeOffer body items { id title } }
  }
}
